"use client";

import type * as React from "react";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
  SidebarRail,
} from "@/core/sidebar/sidebar";
import { useFmaMessages } from "@/lib/i18n/i18n";
import { appSidebarEn, ExternalLabelContext } from "./nav-items";
import { NavUser } from "./nav-user";
import { TeamSwitcher } from "./team-switcher";
import type {
  AppSidebarConfig,
  AppSidebarData,
  AppSidebarTeam,
  AppSidebarUserAction,
} from "./types";

type AppSidebarProps = React.ComponentProps<typeof Sidebar> & {
  data: AppSidebarData;
  onTeamChange?: (team: AppSidebarTeam) => void;
  /** Shows an "Add team" entry in the team switcher. */
  onAddTeam?: () => void;
  onUserAction?: (action: AppSidebarUserAction) => void;
  i18n?: Partial<AppSidebarConfig>;
};

/**
 * App-shell sidebar (shadcn "sidebar-07"): collapsible to icons, with a team
 * switcher or logo, the menus composed in `children` and a user menu. Render it
 * inside a `SidebarProvider`.
 */
export function AppSidebar({
  data,
  onTeamChange,
  onAddTeam,
  onUserAction,
  i18n,
  children,
  ...props
}: AppSidebarProps) {
  const { labels } = useFmaMessages("appSidebar", appSidebarEn, i18n);
  return (
    <Sidebar collapsible="icon" {...props}>
      <SidebarHeader>
        <TeamSwitcher
          teams={data.teams}
          logo={data.logo}
          onTeamChange={onTeamChange}
          onAddTeam={onAddTeam}
        />
      </SidebarHeader>
      <SidebarContent>
        <ExternalLabelContext.Provider value={labels.opensInNewTab}>
          {children}
        </ExternalLabelContext.Provider>
      </SidebarContent>
      <SidebarFooter>
        <NavUser user={data.user} onAction={onUserAction} />
      </SidebarFooter>
      <SidebarRail />
    </Sidebar>
  );
}

export { AppSidebarItem, AppSidebarSection, AppSidebarSubItem, appSidebarEn } from "./nav-items";
export type * from "./types";
export type { AppSidebarProps };

import type { AppSidebarItemAccess, AppSidebarItemBadge } from "./types";

/** The title with the badge, for texts that stand for the whole item. */
export function itemLabel({ title, badge }: { title: string; badge?: AppSidebarItemBadge }) {
  return badge ? `${title}, ${badge.label}` : title;
}

/** A blocked item goes nowhere, so it isn't a link at all. */
export function externalLinkProps({
  external,
  access,
}: {
  external?: boolean;
  access?: AppSidebarItemAccess["access"];
}) {
  return external && access !== "blocked"
    ? ({ target: "_blank", rel: "noopener noreferrer" } as const)
    : {};
}

import { cn } from "cn";
import { ExternalLinkIcon } from "lucide-react";
import { Badge } from "@/core/badge/badge";
import { externalLinkProps } from "./nav-access";
import type { AppSidebarItemAccess, AppSidebarItemBadge } from "./types";

// A sidebar can be as strong as the primary color, so a badge can't use the page's tints: each tone
// is a pair that reads on any sidebar. `tests/app-sidebar-badge-contrast.test.ts` measures them.
export const TONE_BADGE = {
  neutral: "border-sidebar-border bg-sidebar text-sidebar-foreground",
  primary: "bg-sidebar-foreground text-sidebar",
  success: "border-success/30 bg-background text-success-foreground",
  info: "border-info/30 bg-background text-info-foreground",
  warning: "border-warning/30 bg-background text-warning-foreground",
} as const;

// A menu opens on the popover, so the sidebar's colors don't apply there. A focused item recolors
// its content, but a badge has its own surface: `!` and `**:text-inherit!` keep its text.
export const TONE_MENU_BADGE = {
  neutral: "border-border bg-popover text-popover-foreground!",
  primary: "border-primary bg-popover text-popover-foreground!",
  success: "border-success/30 bg-background text-success-foreground!",
  info: "border-info/30 bg-background text-info-foreground!",
  warning: "border-warning/30 bg-background text-warning-foreground!",
} as const;

// The ring keeps a dot visible on a sidebar close to its color.
export const TONE_DOT = {
  neutral: "bg-sidebar ring-1 ring-sidebar-foreground",
  primary: "bg-sidebar-foreground ring-1 ring-sidebar-foreground",
  success: "bg-success ring-1 ring-sidebar-foreground",
  info: "bg-info ring-1 ring-sidebar-foreground",
  warning: "bg-warning ring-1 ring-sidebar-foreground",
} as const;

type NavItemStatusProps = {
  access?: AppSidebarItemAccess["access"];
  badge?: AppSidebarItemBadge;
  external?: boolean;
  /** Read after the title on an external link. */
  externalLabel?: string;
  /** Marks the item with a dot while the sidebar is collapsed to icons. */
  withDot?: boolean;
  /** Rendered in a menu, on the popover instead of the sidebar. */
  inMenu?: boolean;
};

/**
 * What the item says after its title. The screen reader text is one element in every layout: the
 * badge leaves the page when the sidebar collapses, and it would take the reason with it.
 */
export function NavItemStatus({
  access,
  badge,
  external,
  externalLabel,
  withDot = false,
  inMenu = false,
}: NavItemStatusProps) {
  const isExternal = externalLinkProps({ external, access }).target !== undefined;
  if (!badge && !isExternal) return null;

  const tone: NonNullable<AppSidebarItemBadge["tone"]> =
    badge?.tone ?? (access === "gated" ? "primary" : "neutral");
  return (
    <>
      {badge && <span className="sr-only">{` ${badge.label}`}</span>}
      {isExternal && <span className="sr-only">{` ${externalLabel}`}</span>}
      <span
        aria-hidden="true"
        className="ml-auto flex shrink-0 items-center gap-2 group-data-[collapsible=icon]:hidden"
      >
        {badge && (
          <Badge
            variant={null}
            size="xs"
            className={cn(
              inMenu ? [TONE_MENU_BADGE[tone], "**:text-inherit!"] : TONE_BADGE[tone],
              "[&_svg]:size-2.5!",
            )}
          >
            {badge.icon}
            {badge.label}
          </Badge>
        )}
        {isExternal && <ExternalLinkIcon className="size-4" />}
      </span>
      {badge && withDot && (
        <span
          aria-hidden="true"
          className={cn(
            "absolute top-1 right-1 hidden size-1.5 rounded-full group-data-[collapsible=icon]:block",
            TONE_DOT[tone],
          )}
        />
      )}
    </>
  );
}

"use client";

import { ChevronRightIcon, MoreHorizontalIcon } from "lucide-react";
import * as React from "react";
import { Collapsible, CollapsibleContent } from "@/core/collapsible/collapsible";
import {
  DropdownMenu,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/core/dropdown-menu/dropdown-menu";
import {
  SidebarGroup,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarMenuSub,
  SidebarMenuSubButton,
  SidebarMenuSubItem,
  useSidebar,
} from "@/core/sidebar/sidebar";
import type { DictionaryNamespace } from "@/lib/i18n/i18n";
import { externalLinkProps, itemLabel } from "./nav-access";
import { NavItemStatus } from "./nav-item-status";
import type {
  AppSidebarConfig,
  AppSidebarItemProps,
  AppSidebarSectionProps,
  AppSidebarSubItemProps,
} from "./types";

declare global {
  interface FmaNamespaces {
    appSidebar: AppSidebarConfig;
  }
}

export const appSidebarEn: DictionaryNamespace<AppSidebarConfig> = {
  labels: { opensInNewTab: "opens in new tab" },
};

/** Read after the title on an external link; `AppSidebar` provides the active language's. */
export const ExternalLabelContext = React.createContext(appSidebarEn.labels.opensInNewTab);

/** A sub-item's parent decides what it renders as: a sidebar row, or a menu item. */
const SubItemPlacementContext = React.createContext<"sidebar" | "menu">("sidebar");

const isEmpty = (children: React.ReactNode) => React.Children.toArray(children).length === 0;

/** A section of the sidebar. It isn't rendered without items. */
export function AppSidebarSection({ title, children }: AppSidebarSectionProps) {
  if (isEmpty(children)) return null;
  return (
    <SidebarGroup>
      <SidebarGroupLabel>{title}</SidebarGroupLabel>
      <SidebarMenu>{children}</SidebarMenu>
    </SidebarGroup>
  );
}

/**
 * With `children`, a `granted` item opens its sub-items, and isn't rendered without any. Any other
 * access ignores them: a `gated` item links to `href`, and a `blocked` one goes nowhere.
 */
export function AppSidebarItem(props: AppSidebarItemProps) {
  const { isMobile, state } = useSidebar();
  const isIconCollapsed = state === "collapsed" && !isMobile;

  const isGranted = (props.access ?? "granted") === "granted";
  if (!isGranted || (props.children === undefined && props.href !== undefined)) {
    return <LeafItem {...props} />;
  }
  if (isEmpty(props.children)) return null;
  // Icon-only sidebars have no room for inline sub-items.
  const variant = isIconCollapsed ? "dropdown" : (props.variant ?? "collapse");
  return variant === "dropdown" ? (
    <DropdownItem {...props} withLabel={isIconCollapsed} />
  ) : (
    <CollapseItem {...props} />
  );
}

function LeafItem({ title, href, icon, isActive, external, access, badge }: AppSidebarItemProps) {
  const externalLabel = React.useContext(ExternalLabelContext);
  const isBlocked = access === "blocked";
  const isCurrent = isActive && !isBlocked;
  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        href={href ?? ""}
        isInactive={isBlocked}
        isActive={isCurrent}
        aria-current={isCurrent ? "page" : undefined}
        tooltip={itemLabel({ title, badge })}
        {...externalLinkProps({ external, access })}
      >
        {icon}
        <span className="truncate">{title}</span>
        <NavItemStatus
          access={access}
          badge={badge}
          external={external}
          externalLabel={externalLabel}
          withDot
        />
      </SidebarMenuButton>
    </SidebarMenuItem>
  );
}

function CollapseItem({ title, icon, isActive, badge, children }: AppSidebarItemProps) {
  return (
    <SidebarMenuItem>
      <Collapsible defaultExpanded={isActive} className="group/collapsible">
        <SidebarMenuButton slot="trigger" tooltip={itemLabel({ title, badge })}>
          {icon}
          <span className="flex-1 truncate">{title}</span>
          <NavItemStatus badge={badge} withDot />
          <ChevronRightIcon
            aria-hidden="true"
            className="ml-auto shrink-0 transition-transform duration-200 group-data-expanded/collapsible:rotate-90"
          />
        </SidebarMenuButton>
        <CollapsibleContent>
          <SidebarMenuSub className="mr-0 pr-0">{children}</SidebarMenuSub>
        </CollapsibleContent>
      </Collapsible>
    </SidebarMenuItem>
  );
}

function DropdownItem({
  title,
  icon,
  badge,
  children,
  withLabel,
}: AppSidebarItemProps & { withLabel: boolean }) {
  const { isMobile } = useSidebar();
  return (
    <SidebarMenuItem>
      <DropdownMenuTrigger>
        <SidebarMenuButton
          tooltip={itemLabel({ title, badge })}
          className="aria-expanded:bg-sidebar-accent aria-expanded:text-sidebar-accent-foreground"
        >
          {icon}
          <span className="flex-1 truncate">{title}</span>
          <NavItemStatus badge={badge} withDot />
          <MoreHorizontalIcon aria-hidden="true" className="ml-auto shrink-0" />
        </SidebarMenuButton>
        <SubItemPlacementContext.Provider value="menu">
          <DropdownMenu
            aria-label={title}
            placement={isMobile ? "bottom start" : "end top"}
            className="w-fit min-w-40"
          >
            {withLabel && (
              <>
                <DropdownMenuLabel>{title}</DropdownMenuLabel>
                <DropdownMenuSeparator />
              </>
            )}
            {children}
          </DropdownMenu>
        </SubItemPlacementContext.Provider>
      </DropdownMenuTrigger>
    </SidebarMenuItem>
  );
}

/** Each sub-item has its own access, inline or in a menu. */
export function AppSidebarSubItem({
  title,
  href,
  icon,
  external,
  access,
  badge,
}: AppSidebarSubItemProps) {
  const placement = React.useContext(SubItemPlacementContext);
  const externalLabel = React.useContext(ExternalLabelContext);
  const isBlocked = access === "blocked";
  const inMenu = placement === "menu";
  const content = (
    <>
      {icon}
      <span className="truncate">{title}</span>
      <NavItemStatus
        access={access}
        badge={badge}
        external={external}
        externalLabel={externalLabel}
        inMenu={inMenu}
      />
    </>
  );
  if (!inMenu) {
    return (
      <SidebarMenuSubItem>
        <SidebarMenuSubButton
          href={href}
          isInactive={isBlocked}
          className="w-full"
          {...externalLinkProps({ external, access })}
        >
          {content}
        </SidebarMenuSubButton>
      </SidebarMenuSubItem>
    );
  }
  // A disabled menu item can't take focus, and the reason would be out of reach.
  return isBlocked ? (
    <DropdownMenuItem
      id={title}
      textValue={itemLabel({ title, badge })}
      shouldCloseOnSelect={false}
      className="text-muted-foreground"
    >
      {content}
    </DropdownMenuItem>
  ) : (
    <DropdownMenuItem
      id={title}
      href={href}
      textValue={itemLabel({ title, badge })}
      {...externalLinkProps({ external, access })}
    >
      {content}
    </DropdownMenuItem>
  );
}

"use client";

import {
  BadgeCheckIcon,
  BellIcon,
  ChevronsUpDownIcon,
  CreditCardIcon,
  LogOutIcon,
  SparklesIcon,
} from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/core/avatar/avatar";
import {
  DropdownMenu,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/core/dropdown-menu/dropdown-menu";
import {
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "@/core/sidebar/sidebar";
import type { AppSidebarUser, AppSidebarUserAction } from "./types";

function initials(name: string) {
  return name
    .split(/\s+/)
    .slice(0, 2)
    .map((word) => word[0]?.toUpperCase() ?? "")
    .join("");
}

function UserSummary({ user }: { user: AppSidebarUser }) {
  return (
    <>
      <Avatar>
        {user.avatar && <AvatarImage src={user.avatar} alt="" />}
        <AvatarFallback>{initials(user.name)}</AvatarFallback>
      </Avatar>
      <div className="grid flex-1 text-left text-sm leading-tight">
        <span className="truncate font-medium">{user.name}</span>
        <span className="truncate text-xs">{user.email}</span>
      </div>
    </>
  );
}

export function NavUser({
  user,
  onAction,
}: {
  user: AppSidebarUser;
  onAction?: (action: AppSidebarUserAction) => void;
}) {
  const { isMobile } = useSidebar();
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <DropdownMenuTrigger>
          <SidebarMenuButton
            size="lg"
            aria-label={`Account: ${user.name}`}
            className="aria-expanded:bg-sidebar-accent aria-expanded:text-sidebar-accent-foreground"
          >
            <UserSummary user={user} />
            <ChevronsUpDownIcon aria-hidden="true" className="ml-auto size-4" />
          </SidebarMenuButton>
          <DropdownMenu
            placement={isMobile ? "bottom end" : "end bottom"}
            className="w-fit min-w-56"
            onAction={(key) => onAction?.(key as AppSidebarUserAction)}
          >
            <DropdownMenuGroup>
              <DropdownMenuLabel className="flex items-center gap-2 px-1 py-1.5 font-normal text-foreground">
                <UserSummary user={user} />
              </DropdownMenuLabel>
            </DropdownMenuGroup>
            <DropdownMenuSeparator />
            <DropdownMenuItem id="upgrade" textValue="Upgrade to Pro">
              <SparklesIcon aria-hidden="true" />
              Upgrade to Pro
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuGroup>
              <DropdownMenuItem id="account" textValue="Account">
                <BadgeCheckIcon aria-hidden="true" />
                Account
              </DropdownMenuItem>
              <DropdownMenuItem id="billing" textValue="Billing">
                <CreditCardIcon aria-hidden="true" />
                Billing
              </DropdownMenuItem>
              <DropdownMenuItem id="notifications" textValue="Notifications">
                <BellIcon aria-hidden="true" />
                Notifications
              </DropdownMenuItem>
            </DropdownMenuGroup>
            <DropdownMenuSeparator />
            <DropdownMenuItem id="logout" textValue="Log out">
              <LogOutIcon aria-hidden="true" />
              Log out
            </DropdownMenuItem>
          </DropdownMenu>
        </DropdownMenuTrigger>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";

import { ChevronsUpDownIcon, PlusIcon } from "lucide-react";
import * as React from "react";
import {
  DropdownMenu,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuTrigger,
} from "@/core/dropdown-menu/dropdown-menu";
import {
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "@/core/sidebar/sidebar";
import type { AppSidebarLogo, AppSidebarTeam } from "./types";

export function TeamSwitcher({
  teams,
  logo,
  onTeamChange,
  onAddTeam,
}: {
  teams?: AppSidebarTeam[];
  logo?: AppSidebarLogo;
  onTeamChange?: (team: AppSidebarTeam) => void;
  onAddTeam?: () => void;
}) {
  const { isMobile } = useSidebar();
  const [activeTeam, setActiveTeam] = React.useState(teams?.[0]);

  if (!teams?.length || !activeTeam) {
    // Same footprint as the switcher button, so collapsing behaves alike.
    return (
      <SidebarMenu>
        <SidebarMenuItem>
          <div
            data-slot="app-sidebar-logo"
            className="flex h-12 w-full items-center justify-center overflow-hidden rounded-md group-data-[collapsible=icon]:size-8!"
          >
            <div className="flex size-full items-center justify-center group-data-[collapsible=icon]:hidden">
              {logo?.full}
            </div>
            <div className="hidden size-full items-center justify-center group-data-[collapsible=icon]:flex">
              {logo?.collapsed}
            </div>
          </div>
        </SidebarMenuItem>
      </SidebarMenu>
    );
  }

  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <DropdownMenuTrigger>
          <SidebarMenuButton
            size="lg"
            aria-label={`Team: ${activeTeam.name}`}
            className="aria-expanded:bg-sidebar-accent aria-expanded:text-sidebar-accent-foreground"
          >
            <div className="flex aspect-square size-8 items-center justify-center rounded-lg bg-sidebar-primary text-sidebar-primary-foreground">
              {activeTeam.logo}
            </div>
            <div className="grid flex-1 text-left text-sm leading-tight">
              <span className="truncate font-medium">{activeTeam.name}</span>
              <span className="truncate text-xs">{activeTeam.plan}</span>
            </div>
            <ChevronsUpDownIcon aria-hidden="true" className="ml-auto" />
          </SidebarMenuButton>
          <DropdownMenu
            placement={isMobile ? "bottom start" : "end top"}
            className="w-fit min-w-56"
            onAction={(key) => {
              if (key === "add-team") return onAddTeam?.();
              const team = teams.find((candidate) => candidate.name === key);
              if (!team) return;
              setActiveTeam(team);
              onTeamChange?.(team);
            }}
          >
            <DropdownMenuGroup>
              <DropdownMenuLabel>Teams</DropdownMenuLabel>
              {teams.map((team, index) => (
                <DropdownMenuItem key={team.name} id={team.name} className="gap-2 p-2">
                  <div className="flex size-6 items-center justify-center rounded-md border">
                    {team.logo}
                  </div>
                  {team.name}
                  <DropdownMenuShortcut>⌘{index + 1}</DropdownMenuShortcut>
                </DropdownMenuItem>
              ))}
            </DropdownMenuGroup>
            {onAddTeam && (
              <>
                <DropdownMenuSeparator />
                <DropdownMenuItem id="add-team" textValue="Add team" className="gap-2 p-2">
                  <div className="flex size-6 items-center justify-center rounded-md border">
                    <PlusIcon aria-hidden="true" className="size-4" />
                  </div>
                  <span className="font-medium text-muted-foreground">Add team</span>
                </DropdownMenuItem>
              </>
            )}
          </DropdownMenu>
        </DropdownMenuTrigger>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

import type * as React from "react";

/**
 * Contract of the `app-sidebar` block: teams and the user are data, and the
 * menus are composed from `AppSidebarSection`, `AppSidebarItem` and
 * `AppSidebarSubItem`.
 */

export type AppSidebarUser = {
  name: string;
  email: string;
  avatar: string;
};

export type AppSidebarTeam = {
  name: string;
  logo: React.ReactNode;
  plan: string;
};

/**
 * `full` shows while the sidebar is expanded (and on mobile); `collapsed`
 * while it's retracted to icons. Swapped with CSS only.
 */
export type AppSidebarLogo = {
  full: React.ReactNode;
  collapsed: React.ReactNode;
};

/** Either a team switcher or a static logo fills the header. */
export type AppSidebarBranding =
  | { teams: AppSidebarTeam[]; logo?: never }
  | { teams?: never; logo: AppSidebarLogo };

/** The text comes from the app, like `title`. */
export type AppSidebarItemBadge = {
  label: string;
  /** Colors the badge and, while collapsed to icons, the dot on the item. */
  tone?: "neutral" | "primary" | "success" | "info" | "warning";
  icon?: React.ReactNode;
};

/**
 * What the item does; `badge` says why. To hide an item, don't render it.
 * - `granted` (default): a normal link.
 * - `blocked`: visible and focusable, goes nowhere. Requires a badge with the reason.
 * - `gated`: a normal link to `href`, which the app points at the page that resolves it (activate,
 *   upgrade, pay). Informative only: the app must guard the route.
 */
export type AppSidebarItemAccess =
  | { access?: "granted"; badge?: AppSidebarItemBadge }
  | { access: "blocked" | "gated"; badge: AppSidebarItemBadge };

export type AppSidebarSectionProps = {
  title: string;
  children?: React.ReactNode;
};

/**
 * Links are react-aria `Link`s: wrap the app in react-aria's `RouterProvider`
 * to route them client-side. `external` opens one in a new tab instead.
 */
export type AppSidebarSubItemProps = {
  title: string;
  href: string;
  icon?: React.ReactNode;
  external?: boolean;
} & AppSidebarItemAccess;

/**
 * `variant` picks how a `granted` item opens its `children`: `"collapse"` (default) expands them
 * inline, `"dropdown"` opens a menu beside the item. While the sidebar is collapsed to icons every
 * item uses the dropdown. Only that item, which doesn't navigate, can leave out `href`.
 */
export type AppSidebarItemProps = {
  title: string;
  icon?: React.ReactNode;
  /** Marks the current page and starts a collapse item expanded. */
  isActive?: boolean;
  external?: boolean;
  variant?: "collapse" | "dropdown";
} & AppSidebarItemAccess &
  (
    | { href: string; children?: React.ReactNode }
    | { href?: undefined; access?: "granted"; children: React.ReactNode }
  );

export type AppSidebarData = {
  user: AppSidebarUser;
} & AppSidebarBranding;

export type AppSidebarConfig = {
  labels: { opensInNewTab: string };
};

/** Ids of the entries in the user menu, passed to `onUserAction`. */
export type AppSidebarUserAction = "upgrade" | "account" | "billing" | "notifications" | "logout";
